#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/types.hpp"

#include <chrono>
#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// CorrespondenceView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/correspondence_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The selected item's stable ID, or empty; a view, since replacing the items keeps or clears it. A change raises selection_changed; an ID not in the model throws std::out_of_range.
template <typename Declaring>
struct CorrespondenceViewSelectedIdCapability {
    PropertyView<std::string, CorrespondenceViewSelectedIdCapability<Declaring>> selected_id;

    static void assign(CorrespondenceViewSelectedIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_id), std::move(incoming));
    }

    static std::string read(const CorrespondenceViewSelectedIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.selected_id);
        return current;
    }
};

// The pinned (persistently expanded) item's stable ID, or empty; a view, since replacing the items keeps or clears it. A change keeps the visible anchor row, raises pin_changed, then expansion_changed for each item whose expansion changed; an ID not in the model throws std::out_of_range.
template <typename Declaring>
struct CorrespondenceViewPinnedIdCapability {
    PropertyView<std::string, CorrespondenceViewPinnedIdCapability<Declaring>> pinned_id;

    static void assign(CorrespondenceViewPinnedIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.pinned_id), std::move(incoming));
    }

    static std::string read(const CorrespondenceViewPinnedIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.pinned_id);
        return current;
    }
};

// The height of a collapsed row before text scaling, 24 to 192 and below expanded_height (std::invalid_argument otherwise); a view, so a change can keep the visible anchor row.
template <typename Declaring>
struct CorrespondenceViewCompactHeightCapability {
    PropertyView<double, CorrespondenceViewCompactHeightCapability<Declaring>> compact_height;

    static void assign(CorrespondenceViewCompactHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.compact_height), std::move(incoming));
    }

    static double read(const CorrespondenceViewCompactHeightCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.compact_height);
        return current;
    }
};

// The height of an expanded row before text scaling, above compact_height and at most 512 (std::invalid_argument otherwise); a view, so a change can keep the visible anchor row.
template <typename Declaring>
struct CorrespondenceViewExpandedHeightCapability {
    PropertyView<double, CorrespondenceViewExpandedHeightCapability<Declaring>> expanded_height;

    static void assign(CorrespondenceViewExpandedHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.expanded_height), std::move(incoming));
    }

    static double read(const CorrespondenceViewExpandedHeightCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.expanded_height);
        return current;
    }
};

// The width of each row's status rail, 1 to 12 (std::invalid_argument otherwise).
template <typename Declaring>
struct CorrespondenceViewStatusRailWidthCapability {
    PropertyCell<double, CorrespondenceViewStatusRailWidthCapability<Declaring>> status_rail_width{4.0};

    static void assign(CorrespondenceViewStatusRailWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.status_rail_width), incoming);
        if (!capability.status_rail_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.status_rail_width));
    }
};

// How long the pointer must rest on a row before it expands, 1 ms to 5 s (std::invalid_argument otherwise). A change restarts a pending hover.
template <typename Declaring>
struct CorrespondenceViewHoverIntentDelayCapability {
    PropertyCell<std::chrono::milliseconds, CorrespondenceViewHoverIntentDelayCapability<Declaring>> hover_intent_delay{std::chrono::milliseconds(180)};

    static void assign(CorrespondenceViewHoverIntentDelayCapability& capability, std::chrono::milliseconds incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.hover_intent_delay), incoming);
        if (!capability.hover_intent_delay.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.hover_intent_delay));
    }
};

// The vertical scroll position, clamped to the content; a view, since the view's own anchoring and reveal move it. A negative or non-finite offset throws std::invalid_argument; a change ends a pending hover.
template <typename Declaring>
struct CorrespondenceViewScrollOffsetCapability {
    PropertyView<double, CorrespondenceViewScrollOffsetCapability<Declaring>> scroll_offset;

    static void assign(CorrespondenceViewScrollOffsetCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.scroll_offset), std::move(incoming));
    }

    static double read(const CorrespondenceViewScrollOffsetCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.scroll_offset);
        return current;
    }
};

// Every CorrespondenceView capability, in the order the declaring class takes them.
template <typename Declaring>
struct CorrespondenceViewCapabilities : public CorrespondenceViewSelectedIdCapability<Declaring>,
                                        public CorrespondenceViewPinnedIdCapability<Declaring>,
                                        public CorrespondenceViewCompactHeightCapability<Declaring>,
                                        public CorrespondenceViewExpandedHeightCapability<Declaring>,
                                        public CorrespondenceViewStatusRailWidthCapability<Declaring>,
                                        public CorrespondenceViewHoverIntentDelayCapability<Declaring>,
                                        public FontCapability<Declaring>,
                                        public CorrespondenceViewScrollOffsetCapability<Declaring> {
    CorrespondenceViewCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 11.0, 400, false}) {}
};

} // namespace gui_forms
